INSERT INTO modulo (titulo, descricao, ordem, ativo) VALUES ('Análise de Algoritmos', 'Notação Big O: compare O(1), O(n) e O(log n) e descubra como o custo de um algoritmo cresce.', 1, TRUE);
INSERT INTO modulo (titulo, descricao, ordem, ativo) VALUES ('Algoritmos de Busca', 'Busca sequencial e busca binária: encontre valores sem percorrer o reino inteiro.', 2, TRUE);
INSERT INTO modulo (titulo, descricao, ordem, ativo) VALUES ('Algoritmos de Ordenação', 'Bubble, Selection, Insertion, Merge e Quick Sort: coloque o caos em ordem.', 3, TRUE);
INSERT INTO modulo (titulo, descricao, ordem, ativo) VALUES ('Tabelas Hash', 'Funções de espalhamento, colisões e endereçamento: encontre qualquer tesouro no acervo.', 4, TRUE);
INSERT INTO modulo (titulo, descricao, ordem, ativo) VALUES ('Estruturas de Dados', 'Árvores binárias, de busca e balanceamento: domine as ramificações do conhecimento.', 5, TRUE);
